insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('language-acquisition', 'Language Acquisition', 'How readily you infer grammar and meaning from an unfamiliar constructed mini-language — a language-learning aptitude measure.', convert_from(decode('', 'base64'), 'UTF8'), 'book-open', (select id from assessment_categories where key = 'language'), ('standard_questionnaire')::assessment_engine_type, ('hard')::assessment_difficulty, 20, 20, false, ('premium')::assessment_access, ('published')::assessment_status)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'language-acquisition'), 'implicit-learning', 'Implicit Pattern Learning', 'Ability to extract and generalize structure from exposure alone, without explicit rule instruction.', true, 'verbal', 1)
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'language-acquisition'), 'overall', 0, 30, 'Developing', convert_from(decode('Q2xhc3NpZnlpbmcgbm92ZWwgd29yZHMgYnkgImZlZWwiIGFmdGVyIGJyaWVmIGV4cG9zdXJlIGlzIGRpZmZpY3VsdCByaWdodCBub3cg4oCUIHRoaXMgaW1wbGljaXQgcGF0dGVybi1leHRyYWN0aW9uIHNraWxsIHJlc3BvbmRzIHdlbGwgdG8gbW9yZSBleHBvc3VyZSwgbm90IGNvbnNjaW91cyBydWxlLWh1bnRpbmcu', 'base64'), 'UTF8'), ARRAY['Resist the urge to explicitly work out the rule — implicit learning tasks respond better to repeated exposure than analysis', convert_from(decode('Tm90aWNlIHdoaWNoIHNwZWNpZmljIGxldHRlciBjb21iaW5hdGlvbnMgZmVsdCAnb2ZmJyBpbiB3b3JkcyB5b3UgZ290IHdyb25nIOKAlCB0aGF0IGludHVpdGlvbiBpcyB0aGUgc2tpbGwgYnVpbGRpbmc=', 'base64'), 'UTF8'), 'This paradigm mirrors early language exposure — the same mechanism that lets children absorb grammar without being taught rules']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'language-acquisition'), 'overall', 31, 50, 'Average', 'Some sensitivity to the underlying pattern, but longer or more novel words still get misclassified.', ARRAY[convert_from(decode('UmUtcmVhZCB0aGUgc3R1ZHkgZXhhbXBsZXMgYW5kIGxldCBhICdzaGFwZScgb3IgJ3JoeXRobScgb2YgdGhlIHBhdHRlcm4gZm9ybSByYXRoZXIgdGhhbiBjb3VudGluZyBsZXR0ZXJz', 'base64'), 'UTF8'), 'Trust your first instinct on borderline words — implicit learning is often more accurate than deliberate analysis']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'language-acquisition'), 'overall', 51, 70, 'Strong', 'Reliable classification of novel words, including ones structurally different from the exact study examples.', ARRAY[convert_from(decode('VGhpcyBpcyBhIHN0cm9uZyBpbXBsaWNpdC1sZWFybmluZyBzaWduYWwg4oCUIG9mdGVuIGNvcnJlbGF0ZWQgd2l0aCBwaWNraW5nIHVwIGEgbmV3IGxhbmd1YWdlJ3MgZ3JhbW1hciBxdWlja2x5IHRocm91Z2ggaW1tZXJzaW9u', 'base64'), 'UTF8'), convert_from(decode('Tm90aWNlIHdoZXRoZXIgeW91IGNhbiBhcnRpY3VsYXRlIGFueSBvZiB0aGUgcnVsZSBub3csIGV2ZW4gcGFydGlhbGx5IOKAlCB0aGF0J3MgdGhlIGltcGxpY2l0IGtub3dsZWRnZSBzdXJmYWNpbmc=', 'base64'), 'UTF8')]::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'language-acquisition'), 'overall', 71, 85, 'Very Strong', 'Consistently accurate across both grammatical and ungrammatical novel words, generalizing well beyond the study set.', ARRAY['This level of implicit pattern sensitivity is a genuine asset for immersion-based language learning', 'Try noticing patterns in real language input (song lyrics, headlines) the same intuitive way, without analyzing']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'language-acquisition'), 'overall', 86, 100, 'Exceptional', 'Near-perfect classification of novel words — strong implicit extraction of structure from limited exposure.', ARRAY['Consider how immersion-heavy learning methods (rather than rule-first instruction) might suit you especially well for a new language', 'This kind of statistical/structural learning also shows up in music and pattern-heavy domains — worth exploring there too']::text[], NULL, 5);
